<template>
  <div class="row justify-end q-pr-lg q-gutter-sm">
    <f-btn
      :label="$t('send_test')"
      @click="sendTest"
    />
    <f-btn
      :label="$t('save')"
      @click="submitForm"
    />
  </div>

  <q-form @submit="save" ref="saveForm">
    <div class="row">
      <div class="col-3 q-pt-sm q-pl-lg">
        <div>
          <q-input
            outlined
            dense
            :label="$t('name')"
            v-model="email.name"
            lazy-rules
            :rules="[
              (val: string) =>
                (val && val.length > 0) || $t('please_input_name'),
            ]"
          >
          </q-input>
        </div>
        <div>
          <q-input
            outlined
            dense
            :label="$t('subject')"
            v-model="email.subject"
            lazy-rules
            :rules="[
              (val: string) =>
                (val && val.length > 0) || $t('please_input_subject'),
            ]"
          >
          </q-input>
        </div>
        <div>
          <q-select
            :label="$t('select_email_template')"
            map-options
            dense
            outlined
            v-model="email.supplier_type"
            :options="supplierEmailOptions"
            emit-value
            @update:model-value="selectEmailChange"
            lazy-rules
            :rules="[
              (val: string) =>
                (val && val.length > 0) || $t('please_select_type'),
            ]"
          >
          </q-select>
        </div>
        <div>
          <q-select
            multiple
            :label="$t('CC')"
            map-options
            dense
            outlined
            v-model="email.cc_type"
            :options="cc_type"
            emit-value
          >
          </q-select>
        </div>
      </div>

      <div
        class="col-9 q-pt-sm q-pl-lg q-pr-lg height-100vh-120px"
        ref="editorContainer"
      >
        <div v-if="!view_source" class="editor-wrapper">
          <q-editor
            :style="`min-height:28rem;height: ${editorHeight}px;max-height: ${editorHeight}px;`"
            v-model="email.editor_value"
            ref="editorRef"
            :definitions="{
              upload: {
                tip: 'Upload to cloud',
                icon: 'cloud_upload',
                label: 'Upload',
                handler: openFileDialog,
              },
              viewsource: {
                icon: 'code',
                handler: openViewSource,
              },
            }"
            :toolbar="[
              ['left', 'center', 'right', 'justify'],
              ['quote', 'unordered', 'ordered', 'outdent', 'indent'],
              ['viewsource'],
              ['bold', 'italic', 'strike', 'underline'],
              ['undo', 'redo'],
              ['upload'],
              ['properties'],
            ]"
          >
            <template v-slot:properties>
              <Properties
                :filteredDataKey="filteredDataKey"
                :editorRef="editorRef"
              />
            </template>
          </q-editor>
          <input
            type="file"
            ref="fileInput"
            class="hide"
            @change="handleFileUpload"
          />
        </div>
        <div v-else>
          <q-icon
            name="code"
            class="q-pb-sm cursor-pointer font-size-18"
            @click="backToEditor"
          >
          </q-icon>
          <q-icon
            name="edit_note"
            class="format-icon cursor-pointer q-pb-sm"
            @click="formatCode"
          >
            <q-tooltip>{{ $t('format_button') }}</q-tooltip>
          </q-icon>
          <Editor
            :editorValue="email.editor_value"
            :formatCode="is_format_code"
            @updated-value="updateValue"
            @formatComplete="afterFormatted"
          />
        </div>
      </div>
    </div>
  </q-form>

  <q-dialog v-model="send_test_dialog" persistent>
    <q-card class="width-500">
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title>
          <span class="text-weight-bold text-capitalize">{{
            $t('send_test')
          }}</span>
        </q-toolbar-title>
        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-form @submit="submitSendTest">
        <q-card-section>
          <div class="row">
            <div class="width-100-percent">
              <q-input
                outlined
                dense
                :label="$t('receiver_email')"
                v-model="email.receiver_email"
                :rules="[
                  (val: string) =>
                    (val && val.length > 0) || $t('please_input_email'),
                  (val: string) => isValidEmail(val) || $t('invalid_email'),
                ]"
              >
              </q-input>
            </div>
          </div>
          <div class="properties" v-if="filteredDataKey.length">
            <div
              v-for="(data, index) in filteredDataKey as any"
              :key="data.index"
              :class="index ? 'properties-child' : ''"
            >
              <q-input
                outlined
                dense
                :label="data.name"
                v-model="filteredDataValues[data.key]"
              >
                <template v-slot:append>
                  <q-icon
                    name="content_copy"
                    class="cursor-pointer font-size-16"
                    @click="clickToCopyKey(data.key)"
                  >
                    <q-tooltip>{{ $t('click_to_copy_key') }}</q-tooltip>
                  </q-icon>
                </template>
              </q-input>
            </div>
          </div>
        </q-card-section>

        <q-card-actions align="right">
          <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
          <f-btn
            class="q-mr-sm"
            data-cy="setvatfield"
            :label="$t('send')"
            type="submit"
          />
        </q-card-actions>
      </q-form>
    </q-card>
  </q-dialog>

  <q-inner-loading :showing="loading" class="z-index-2">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import { emailTemplateStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import { ApiExceptions } from 'src/exceptions';
import { useTranslate } from '@tolgee/vue';
import type { dynamicObj } from 'src/pages/assets';
import { copyToClipboard } from 'quasar';
import Editor from 'src/pages/Settings/SupplierEmailTemplate/Editor.vue';
import Properties from 'src/pages/Settings/Components/EmailTemplate/Properties.vue';
export default defineComponent({
  el: '#app',
    components: {
    Editor,
    Properties,
  },
  mounted() {
    this.init();
    this.setEditorHeight();
    window.addEventListener('resize', this.setEditorHeight);
  },
  unmounted() {
    window.removeEventListener('resize', this.setEditorHeight);
  },
  watch: {
    'email.supplier_type': function (newVal) {
      const emailItem = this.sample_data.filter(
        (item: dynamicObj) => item.email_type === newVal,
      );
      if (emailItem.length > 0) {
        emailItem.map((item: any) => {
          console.log(item.data_key);
          this.filteredDataKey = item.data_key;
        });
      }
    },
  },
  methods: {
    setEditorHeight() {
      this.$nextTick(function () {
        const container = this.$refs.editorContainer as HTMLElement;
        if (container) {
          const parentHeight = container.getBoundingClientRect().height;
          this.editorHeight = parentHeight;
        }
      });
    },
    formatCode() {
      this.is_format_code = true;
    },
    afterFormatted(value: any) {
      this.is_format_code = value;
    },
    isValidEmail(email: string) {
      const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      return re.test(email);
    },
    updateValue(value: string) {
      this.email.editor_value = value;
    },
    openViewSource() {
      this.view_source = true;
    },
    backToEditor() {
      this.view_source = false;
    },
    async init() {
      await this.getSampleTemplatedata();
    },
    async getSampleTemplatedata() {
      try {
        await this.getSampleData();
      } catch (err: any) {
        logError(err);
      }
    },
    submitForm() {
      const form = this.$refs.saveForm as any;
      form.submit();
    },
    async save() {
      try {
        if (!this.email.editor_value.trim()) {
          notify.error(this.t('email_content_empty'));
          return;
        } else {
          this.loading = true;
          const response = await this.createEmailTemplate(this.email);
          if (!response || response.success === false) {
            throw response;
          }
          this.resetEmailData();
          this.$router.push('/settings/supplier/email-templates');
          notify.success(this.t('email_template_created_success'));
        }
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    sendTest() {
      this.send_test_dialog = true;
    },
    async submitSendTest() {
      try {
        this.send_test_dialog = false;
        this.loading = true;

        this.prepareDataSend = {
          receiver_email: this.email.receiver_email,
          subject: this.email.subject,
          body: this.email.editor_value,
          data: { ...this.filteredDataValues },
        };

        const response = await this.sendTestEmail(this.prepareDataSend);
        if (response) {
          notify.success(this.t('email_send_successfully'));
        }
        this.email.receiver_email = '';
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err);
        notify.error(msg);
      } finally {
        this.loading = false;
      }
    },
    openFileDialog() {
      const fileInput = this.$refs.fileInput as HTMLInputElement;
      if (fileInput) {
        fileInput.click();
      }
    },
    async handleFileUpload(event: Event) {
      const input = event.target as HTMLInputElement;
      if (input.files && input.files[0]) {
        const file = input.files[0];
        await this.onUploadFile(file);

        if (file.type.startsWith('image/')) {
          this.insertImageToEditor(this.stream_file_data);
        } else {
          this.insertFileLinkToEditor(this.stream_file_data, file.name);
        }
      }
    },
    insertImageToEditor(imageUrl: string) {
      this.email.editor_value += `<img src="${imageUrl}" alt="Uploaded Image" />`;
    },
    insertFileLinkToEditor(fileUrl: string, fileName: string) {
      const linkHtml = `<a class="cursor-pointer" href="${fileUrl}" target="_blank">${fileName}</a>`;
      this.email.editor_value += linkHtml;
    },
    selectEmailChange(value: string) {
      this.email.supplier_type = value;
    },
    resetEmailData() {
      this.email.name = '';
      this.email.subject = '';
      this.email.supplier_type = '';
      this.email.editor_value = '';
      this.email.receiver_email = '';
      this.filteredDataKey = [];
      this.filteredDataValues = [];
    },
    async clickToCopyKey(key: string) {
      const key_copy = `{{${key}}}`;
      await copyToClipboard(key_copy);
      notify.success(this.t('copy_key_successfully'));
    },
  },
  data() {
    return {
      files: ref(null),
      email: {
        name: '',
        subject: '',
        supplier_type: '',
        editor_value: '',
        receiver_email: '',
        cc_type: [],
      },
      filteredDataKey: ref([]),
      filteredDataValues: ref([]),
      prepareDataSend: {},
      view_source: ref(false),
      is_format_code: ref(false),
      editorHeight: 0,
    };
  },
  setup() {
    const email_template = emailTemplateStore();
    const propertiesMenu = ref(null);
    const editorRef = ref(null) as any;
    const { loading, send_test_dialog, sample_data, stream_file_data } =
      storeToRefs(email_template);
    const { createEmailTemplate, getSampleData, sendTestEmail, onUploadFile } =
      email_template;

    const { t } = useTranslate();

    return {
      t,
      editorRef,
      createEmailTemplate,
      getSampleData,
      sendTestEmail,
      onUploadFile,
      loading,
      sample_data,
      send_test_dialog,
      stream_file_data,
      supplierEmailOptions: [
        {
          label: 'Supplier Invitation Email',
          value: 'supplier_invite',
        },
        {
          label: 'Supplier Registration Completion Email',
          value: 'supplier_register',
        },
        {
          label: 'Supplier Approval Email',
          value: 'supplier_approve',
        },
        {
          label: 'Supplier Rejection Email',
          value: 'supplier_reject',
        },
      ],
      cc_type: [
        {
          label: 'Assigned User',
          value: 'assigned_user',
        },
        {
          label: 'Referrer',
          value: 'referrer',
        },
      ],
    };
  },
});
</script>

